+function runGitCommand(
+  args: string[],
+  options: {
+    cwd: string;
+    env: NodeJS.ProcessEnv;
+  },
+): Promise<{ stdout: string }> {
+  const [command, ...commandArgs] = args;
+  if (command === undefined) {
+    return Promise.resolve({ stdout: "" });
+  }
+  return execFileAsync(command, commandArgs, options);
+}
